import { describe, expect, it } from "vitest";
import { tokenRequest } from "../lib/auth.js";

const cfg = {
  keycloakUrl: "http://kc:8080",
  realm: "omnicore",
  seedClientId: "omnicore-seed",
  seedClientSecret: "s3cret",
  userPassword: "password1234",
};

describe("tokenRequest", () => {
  it("targets the realm's OIDC token endpoint", () => {
    expect(tokenRequest(cfg, "a@x").url).toBe(
      "http://kc:8080/realms/omnicore/protocol/openid-connect/token",
    );
  });

  it("uses the ROPC password grant, matching seed.sh", () => {
    expect(tokenRequest(cfg, "a@x").body.grant_type).toBe("password");
  });

  it("sends the seed client id and secret", () => {
    const { body } = tokenRequest(cfg, "a@x");
    expect(body.client_id).toBe("omnicore-seed");
    expect(body.client_secret).toBe("s3cret");
  });

  it("sends the per-user credentials", () => {
    const { body } = tokenRequest(cfg, "a@x");
    expect(body.username).toBe("a@x");
    expect(body.password).toBe("password1234");
  });

  it("requests the openid scope", () => {
    expect(tokenRequest(cfg, "a@x").body.scope).toBe("openid");
  });

  it("form-encodes the request", () => {
    expect(tokenRequest(cfg, "a@x").params.headers["Content-Type"]).toBe(
      "application/x-www-form-urlencoded",
    );
  });

  it("tags the mint so setup traffic never pollutes a surface's metrics", () => {
    expect(tokenRequest(cfg, "a@x").params.tags).toEqual({
      surface: "auth",
      vertical: "platform",
      scenario: "token-mint",
    });
  });
});


