import { describe, expect, it } from "vitest";
import { buildConfig, DEFAULTS, REQUIRED_KEYS } from "../lib/config.js";

const MINIMAL = { OIDC_SEED_CLIENT_SECRET: "s3cret" };

describe("buildConfig", () => {
  it("throws listing every missing required key", () => {
    expect(() => buildConfig({})).toThrow(/OIDC_SEED_CLIENT_SECRET/);
  });

  it("treats an empty string as absent so a blank compose var falls back", () => {
    expect(() => buildConfig({ OIDC_SEED_CLIENT_SECRET: "" })).toThrow(
      /OIDC_SEED_CLIENT_SECRET/,
    );
    const cfg = buildConfig({ ...MINIMAL, KEYCLOAK_REALM: "" });
    expect(cfg.realm).toBe(DEFAULTS.KEYCLOAK_REALM);
  });

  it("applies defaults for everything not required", () => {
    const cfg = buildConfig(MINIMAL);
    expect(cfg.shellBffUrl).toBe("http://localhost:8082");
    expect(cfg.keycloakUrl).toBe("http://localhost:8080");
    expect(cfg.realm).toBe("omnicore");
    expect(cfg.seedClientId).toBe("omnicore-seed");
    expect(cfg.userPassword).toBe("password1234");
    expect(cfg.suite).toBe("smoke");
    expect(cfg.outDir).toBe("/out");
  });

  it("carries the required secret through", () => {
    expect(buildConfig(MINIMAL).seedClientSecret).toBe("s3cret");
  });

  it("strips trailing slashes so path concatenation never doubles up", () => {
    const cfg = buildConfig({ ...MINIMAL, SHELL_BFF_URL: "http://sb:8080/" });
    expect(cfg.shellBffUrl).toBe("http://sb:8080");
  });

  it("splits LOAD_USERNAMES on commas and trims each entry", () => {
    const cfg = buildConfig({ ...MINIMAL, LOAD_USERNAMES: "a@x.local, b@x.local " });
    expect(cfg.usernames).toEqual(["a@x.local", "b@x.local"]);
  });

  it("defaults to the single seeded workspace user", () => {
    expect(buildConfig(MINIMAL).usernames).toEqual([
      "owner.wsadmin@seed.omnicore.local",
    ]);
  });

  it("rejects an empty username roster", () => {
    expect(() => buildConfig({ ...MINIMAL, LOAD_USERNAMES: " , " })).toThrow(
      /LOAD_USERNAMES/,
    );
  });

  it("returns a frozen object so no scenario can mutate shared config", () => {
    expect(Object.isFrozen(buildConfig(MINIMAL))).toBe(true);
  });

  it("declares OIDC_SEED_CLIENT_SECRET as the only required key", () => {
    expect(REQUIRED_KEYS).toEqual(["OIDC_SEED_CLIENT_SECRET"]);
  });
});


