import { describe, expect, it } from "vitest";
import {
  bearerHeaders,
  classify,
  EXPECTED_STATUS,
  requestTags,
  THROTTLED_STATUS,
} from "../lib/http.js";

describe("requestTags", () => {
  it("emits the three tags every metric is sliced by", () => {
    expect(requestTags({ surface: "shell", vertical: "files", scenario: "list" })).toEqual({
      surface: "shell",
      vertical: "files",
      scenario: "list",
    });
  });

  it("rejects a missing tag rather than emitting an unsliceable metric", () => {
    expect(() => requestTags({ surface: "shell", vertical: "files" })).toThrow(/scenario/);
  });
});

describe("classify", () => {
  it("treats 2xx and 3xx as ok", () => {
    expect(classify(200)).toBe("ok");
    expect(classify(204)).toBe("ok");
    expect(classify(302)).toBe("ok");
  });

  it("treats 429 as throttled, NOT as an error", () => {
    expect(classify(429)).toBe("throttled");
  });

  it("treats other 4xx as client errors", () => {
    expect(classify(401)).toBe("client_error");
    expect(classify(404)).toBe("client_error");
  });

  it("treats 5xx as server errors", () => {
    expect(classify(500)).toBe("server_error");
    expect(classify(503)).toBe("server_error");
  });

  it("treats k6's status 0 (connection failure) as a server error", () => {
    expect(classify(0)).toBe("server_error");
  });
});

describe("expected-status constants", () => {
  it("spans 2xx-3xx", () => {
    expect(EXPECTED_STATUS).toEqual({ min: 200, max: 399 });
  });

  it("names 429 so the k6 response callback can whitelist it", () => {
    expect(THROTTLED_STATUS).toBe(429);
  });
});

describe("bearerHeaders", () => {
  it("builds an Authorization header shell-bff's CookieToBearer passes through", () => {
    expect(bearerHeaders("abc")).toEqual({ Authorization: "Bearer abc" });
  });

  it("throws on a missing token rather than sending 'Bearer undefined'", () => {
    expect(() => bearerHeaders(undefined)).toThrow(/token/);
  });
});


