import { describe, expect, it } from "vitest";
import { assignIdentity, buildRoster } from "../lib/orgs.js";

const cfg = (usernames) => ({ usernames });

describe("buildRoster", () => {
  it("produces one entry per configured username, index-stamped", () => {
    expect(buildRoster(cfg(["a@x", "b@x"]))).toEqual([
      { username: "a@x", index: 0 },
      { username: "b@x", index: 1 },
    ]);
  });

  it("freezes the roster so a scenario cannot mutate shared setup data", () => {
    expect(Object.isFrozen(buildRoster(cfg(["a@x"])))).toBe(true);
  });
});

describe("assignIdentity", () => {
  const roster = buildRoster(cfg(["a@x", "b@x", "c@x"]));

  it("maps VU 1 to the first identity (k6 numbers VUs from 1)", () => {
    expect(assignIdentity(roster, 1).username).toBe("a@x");
  });

  it("distributes VUs round-robin across the roster", () => {
    expect([1, 2, 3].map((vu) => assignIdentity(roster, vu).username)).toEqual([
      "a@x",
      "b@x",
      "c@x",
    ]);
  });

  it("wraps when there are more VUs than identities", () => {
    expect(assignIdentity(roster, 4).username).toBe("a@x");
    expect(assignIdentity(roster, 5).username).toBe("b@x");
  });

  it("is deterministic — the same VU always gets the same identity", () => {
    expect(assignIdentity(roster, 7)).toEqual(assignIdentity(roster, 7));
  });

  it("throws on an empty roster rather than returning undefined", () => {
    expect(() => assignIdentity([], 1)).toThrow(/empty roster/);
  });

  it("throws on a non-positive VU — k6 VUs start at 1", () => {
    expect(() => assignIdentity(roster, 0)).toThrow(/VU/);
  });
});


