import { describe, expect, it } from "vitest";
import { redactSummary, renderMarkdown } from "../lib/summary.js";

const data = {
  metrics: {
    "http_reqs{surface:shell}": { values: { count: 120 } },
    "http_req_duration{surface:shell}": {
      values: { "p(95)": 142.5, "p(99)": 310.25, avg: 55.1 },
    },
    "http_req_failed{surface:shell}": { values: { rate: 0.0 } },
    "http_reqs{surface:auth}": { values: { count: 1 } },
    "http_req_duration{surface:auth}": { values: { avg: 4.6, "p(95)": 4.6, "p(99)": 4.6 } },
    "http_req_failed{surface:auth}": { values: { rate: 0.0 } },
    throttled: { values: { count: 3 } },
  },
};

describe("renderMarkdown", () => {
  it("renders a heading", () => {
    expect(renderMarkdown(data)).toContain("## k6 load test");
  });

  it("renders a markdown table header with a Surface column", () => {
    expect(renderMarkdown(data)).toContain(
      "| Surface | Requests | Avg duration | p95 duration | p99 duration | Failure rate |",
    );
  });

  it("reports one row per surface rather than a single blended row", () => {
    const out = renderMarkdown(data);
    expect(out).toContain("| shell | 120 | 55.10 ms | 142.50 ms | 310.25 ms | 0.00% |");
    expect(out).toContain("| auth | 1 | 4.60 ms | 4.60 ms | 4.60 ms | 0.00% |");
  });

  it("does not blend the auth (token-mint) surface into the load surface's numbers", () => {
    // Regression guard for the real bug: a 4.6ms mint + a 65ms session call
    // used to average into a single meaningless 34.83ms row.
    const out = renderMarkdown(data);
    expect(out).not.toContain("34.83");
  });

  it("reports throttled (429) responses separately from failures", () => {
    expect(renderMarkdown(data)).toContain("Throttled (429): 3");
  });

  it("reports zero throttled when the counter never fired", () => {
    const out = renderMarkdown({ metrics: { ...data.metrics, throttled: undefined } });
    expect(out).toContain("Throttled (429): 0");
  });

  it("degrades a surface's missing field to n/a rather than throwing", () => {
    const out = renderMarkdown({
      metrics: { "http_req_duration{surface:shell}": { values: {} } },
    });
    expect(out).toContain("| shell | n/a | n/a | n/a | n/a | n/a |");
  });

  it("degrades to a placeholder row when no surface is tagged at all", () => {
    const out = renderMarkdown({ metrics: {} });
    expect(out).toContain("| n/a | n/a | n/a | n/a | n/a | n/a |");
  });

  it("tolerates a summary with no metrics object at all", () => {
    expect(() => renderMarkdown({})).not.toThrow();
  });

  it("states plainly that a crossed threshold still exits the run", () => {
    const out = renderMarkdown(data);
    expect(out).toContain("still exits the process with code 99");
    expect(out).not.toContain("do not fail the run");
  });
});

describe("redactSummary", () => {
  const raw = Object.freeze({
    setup_data: Object.freeze({
      cfg: Object.freeze({ shellBffUrl: "http://shell-bff:8080" }),
      roster: Object.freeze([{ username: "a@x", index: 0 }]),
      tokens: Object.freeze({ "a@x": "eyJhbGciOi...verylongbearertoken" }),
    }),
    root_group: {},
    metrics: data.metrics,
  });

  it("removes the setup_data key", () => {
    expect(redactSummary(raw)).not.toHaveProperty("setup_data");
  });

  it("does not mutate its input", () => {
    redactSummary(raw);
    expect(raw).toHaveProperty("setup_data");
    expect(raw.setup_data.tokens).toHaveProperty("a@x");
  });

  it("keeps every other top-level key untouched", () => {
    const redacted = redactSummary(raw);
    expect(redacted.metrics).toBe(raw.metrics);
    expect(redacted.root_group).toBe(raw.root_group);
  });

  it("never lets a bearer token or secret survive into the redacted object", () => {
    const redacted = redactSummary(raw);
    expect(JSON.stringify(redacted)).not.toContain("verylongbearertoken");
  });

  it("tolerates a payload with no setup_data key", () => {
    expect(() => redactSummary({ metrics: {} })).not.toThrow();
    expect(redactSummary({ metrics: {} })).toEqual({ metrics: {} });
  });

  it("tolerates a nullish payload without throwing", () => {
    expect(() => redactSummary(undefined)).not.toThrow();
    expect(() => redactSummary(null)).not.toThrow();
  });
});


