import { describe, expect, it } from "vitest";
import { ADVISORY_LIMITS, buildThresholds, SURFACES } from "../lib/thresholds.js";

const HTTP_SURFACES = ["shell", "bff"];

describe("buildThresholds", () => {
  it("uses the spec's advisory limits by default", () => {
    expect(ADVISORY_LIMITS).toEqual({ p95: 300, p99: 800, failRate: 0.01 });
  });

  it("names the four surfaces from the design as the taxonomy constant", () => {
    expect(SURFACES).toEqual(["shell", "bff", "ws", "grpc"]);
  });

  it("scopes every threshold to the surface tag", () => {
    const t = buildThresholds(["shell"]);
    expect(Object.keys(t).sort()).toEqual([
      "http_req_duration{surface:shell}",
      "http_req_failed{surface:shell}",
    ]);
  });

  it("emits p95 and p99 duration thresholds", () => {
    const t = buildThresholds(["shell"]);
    expect(t["http_req_duration{surface:shell}"].map((x) => x.threshold)).toEqual([
      "p(95)<300",
      "p(99)<800",
    ]);
  });

  it("emits a failure-rate threshold", () => {
    const t = buildThresholds(["bff"]);
    expect(t["http_req_failed{surface:bff}"][0].threshold).toBe("rate<0.01");
  });

  it("marks every threshold abortOnFail:false (still blocking on a crossed limit — see module header)", () => {
    const t = buildThresholds(HTTP_SURFACES);
    const all = Object.values(t).flat();
    expect(all.length).toBeGreaterThan(0);
    expect(all.every((x) => x.abortOnFail === false)).toBe(true);
  });

  it("covers each requested HTTP surface independently", () => {
    const t = buildThresholds(["shell", "bff"]);
    expect(t).toHaveProperty("http_req_duration{surface:shell}");
    expect(t).toHaveProperty("http_req_duration{surface:bff}");
    expect(t).not.toHaveProperty("http_req_duration{surface:ws}");
  });

  it("accepts overridden limits for the eventual ratchet", () => {
    const t = buildThresholds(["shell"], { p95: 150, p99: 400, failRate: 0.005 });
    expect(t["http_req_duration{surface:shell}"][0].threshold).toBe("p(95)<150");
    expect(t["http_req_failed{surface:shell}"][0].threshold).toBe("rate<0.005");
  });

  it("rejects an unknown surface rather than silently emitting a dead threshold", () => {
    expect(() => buildThresholds(["nope"])).toThrow(/nope/);
  });

  it("rejects ws with an actionable error naming the real metric names", () => {
    expect(() => buildThresholds(["ws"])).toThrow(/ws_connecting/);
    expect(() => buildThresholds(["ws"])).toThrow(/sub-PR 5/);
  });

  it("rejects grpc with an actionable error naming the real metric names", () => {
    expect(() => buildThresholds(["grpc"])).toThrow(/grpc_req_duration/);
    expect(() => buildThresholds(["grpc"])).toThrow(/sub-PR 6/);
  });

  it("rejects the full SURFACES taxonomy as-is — ws/grpc are not buildable here", () => {
    expect(() => buildThresholds(SURFACES)).toThrow(/ws|grpc/);
  });
});



